BEGIN;
CREATE TYPE procurement_stage AS ENUM ('RFQ', 'FORMAL_TENDER', 'INTERNAL');
CREATE TABLE tenders (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, title text NOT NULL, reference text, procurement_stage procurement_stage NOT NULL, created_by_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tender_lots (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, tender_id uuid NOT NULL REFERENCES tenders(id) ON DELETE CASCADE, lot_code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (tender_id, lot_code), UNIQUE (id, organization_id));
CREATE TABLE tender_items (id uuid PRIMARY KEY, organization_id uuid NOT NULL, lot_id uuid NOT NULL, item_no text NOT NULL, name text NOT NULL, quantity numeric(14,3) NOT NULL CHECK (quantity > 0), unit text NOT NULL CHECK (length(btrim(unit)) > 0), description text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (lot_id, item_no), FOREIGN KEY (lot_id, organization_id) REFERENCES tender_lots(id, organization_id) ON DELETE CASCADE);
CREATE INDEX tenders_org_created_idx ON tenders(organization_id, created_at, id); CREATE INDEX tender_lots_org_tender_idx ON tender_lots(organization_id, tender_id); CREATE INDEX tender_items_org_lot_idx ON tender_items(organization_id, lot_id);
GRANT SELECT, INSERT, UPDATE ON tenders, tender_lots, tender_items TO medtender_app;
ALTER TABLE tenders ENABLE ROW LEVEL SECURITY; ALTER TABLE tenders FORCE ROW LEVEL SECURITY; ALTER TABLE tender_lots ENABLE ROW LEVEL SECURITY; ALTER TABLE tender_lots FORCE ROW LEVEL SECURITY; ALTER TABLE tender_items ENABLE ROW LEVEL SECURITY; ALTER TABLE tender_items FORCE ROW LEVEL SECURITY;
CREATE POLICY tender_scope ON tenders FOR ALL TO medtender_app USING (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
CREATE POLICY tender_lot_scope ON tender_lots FOR ALL TO medtender_app USING (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
CREATE POLICY tender_item_scope ON tender_items FOR ALL TO medtender_app USING (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
COMMIT;
